//     (localeInfo) holding the header words and per-locale date/amount
//     formatters.
//  4. Replaced the duplicated currency checks with a currencySymbols map.
//  5. Extracted date validation (length + separators) into validateDate.
//  6. Extracted amount formatting into a shared formatCents helper that
//     takes the thousands/decimal separators, with small per-locale
//     wrappers for the currency symbol placement and negative-number
//     notation (parentheses in en-US, trailing "-" in nl-NL).
//  7. Removed the empty-entries hack that called FormatLedger recursively
//     with a dummy entry just to trigger currency validation; currency and
//     locale are now validated up front, so an empty ledger with a bad
//     currency also fails as the tests require.
//  8. Built the output with strings.Builder instead of repeated string
//     concatenation.
package ledger

import (
	"errors"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var (
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidDate     = errors.New("invalid date")
)

const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

// localeInfo describes how to render the table for one locale.
type localeInfo struct {
	dateHeader        string
	descriptionHeader string
	changeHeader      string
	date              func(year, month, day string) string
	amount            func(symbol string, cents int) string
}

var locales = map[string]localeInfo{
	"en-US": {
		dateHeader:        "Date",
		descriptionHeader: "Description",
		changeHeader:      "Change",
		date: func(year, month, day string) string {
			return month + "/" + day + "/" + year
		},
		amount: amountUS,
	},
	"nl-NL": {
		dateHeader:        "Datum",
		descriptionHeader: "Omschrijving",
		changeHeader:      "Verandering",
		date: func(year, month, day string) string {
			return day + "-" + month + "-" + year
		},
		amount: amountNL,
	},
}

var currencySymbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	info, ok := locales[locale]
	if !ok {
		return "", errInvalidLocale
	}
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", errInvalidCurrency
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var b strings.Builder
	b.WriteString(info.dateHeader)
	b.WriteString(pad(info.dateHeader, dateWidth))
	b.WriteString(" | ")
	b.WriteString(info.descriptionHeader)
	b.WriteString(pad(info.descriptionHeader, descriptionWidth))
	b.WriteString(" | ")
	b.WriteString(info.changeHeader)
	b.WriteString(pad(info.changeHeader, changeWidth))
	b.WriteByte('\n')

	for _, e := range sorted {
		year, month, day, err := validateDate(e.Date)
		if err != nil {
			return "", err
		}
		date := info.date(year, month, day)
		b.WriteString(date)
		b.WriteString(pad(date, dateWidth))
		b.WriteString(" | ")
		b.WriteString(truncate(e.Description))
		b.WriteString(" | ")
		amount := info.amount(symbol, e.Change)
		b.WriteString(pad(amount, changeWidth))
		b.WriteByte('\n')
	}
	return b.String(), nil
}

// validateDate checks that date is "YYYY-MM-DD" and returns its parts.
func validateDate(date string) (year, month, day string, err error) {
	if len(date) != dateWidth || date[4] != '-' || date[7] != '-' {
		return "", "", "", errInvalidDate
	}
	return date[0:4], date[5:7], date[8:10], nil
}

// truncate pads a description to descriptionWidth, or shortens it with an
// ellipsis if it is too long.
func truncate(s string) string {
	if len(s) > descriptionWidth {
		return s[:descriptionWidth-3] + "..."
	}
	return s + pad(s, descriptionWidth)
}

// pad right-aligns s in a field of width w (measured in runes).
func pad(s string, width int) string {
	return strings.Repeat(" ", width-utf8.RuneCountInString(s))
}

// amountUS renders an amount in US style: "$10.00 " or "($10.00)".
func amountUS(symbol string, cents int) string {
	v := formatCents(cents, ",", ".")
	if cents < 0 {
		return "(" + symbol + v + ")"
	}
	return symbol + v + " "
}

// amountNL renders an amount in Dutch style: "$ 10,00 " or "$ 10,00-".
func amountNL(symbol string, cents int) string {
	v := formatCents(cents, ".", ",")
	if cents < 0 {
		return symbol + " " + v + "-"
	}
	return symbol + " " + v + " "
}

// formatCents formats a non-negative magnitude of cents with the given
// thousands and decimal separators, e.g. 123456 -> "1234.56".
func formatCents(cents int, thousandsSep, decimalSep string) string {
	if cents < 0 {
		cents = -cents
	}
	s := strconv.Itoa(cents)
	for len(s) < 3 {
		s = "0" + s
	}
	digits, frac := s[:len(s)-2], s[len(s)-2:]
	var b strings.Builder
	for i, r := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteString(thousandsSep)
		}
		b.WriteRune(r)
	}
	return b.String() + decimalSep + frac
}
"}
